package main

import (
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/google/go-cmp/cmp"
)

const contract = `openapi: 3.0.3
info: {title: t, version: v1}
paths:
  /a:
    get:
      operationId: getA
      responses: {"200": {description: ok}}
  /b:
    post:
      operationId: makeB
      responses: {"204": {description: ok}}
  /c:
    get:
      operationId: listC
      responses: {"200": {description: ok}}
`

// TestRun: the type gets a method for every operation the handler type does not declare, whichever way it declares
// it, and the generated file and the tests are not read as declarations.
func TestRun(t *testing.T) {
	dir := t.TempDir()
	write := func(name, text string) {
		t.Helper()
		if err := os.WriteFile(filepath.Join(dir, name), []byte(text), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	write("api.yaml", contract)
	write("handler.go", "package main\n\ntype api struct{}\n\nfunc (api) GetA() {}\n\nfunc (*api) other() {}\n\ntype elsewhere struct{}\n\nfunc (elsewhere) MakeB() {}\n")
	write("handler_test.go", "package main\n\nfunc (api) ListC() {}\n")
	write("stubs.gen.go", "package main\n\nfunc (api) ListC() {}\n")
	if err := run(filepath.Join(dir, "api.yaml"), dir, "stubs.gen.go", "example.test/apis/things", "api", "pending"); err != nil {
		t.Fatal(err)
	}
	out, err := fs.ReadFile(os.DirFS(dir), "stubs.gen.go")
	if err != nil {
		t.Fatal(err)
	}
	var methods []string
	for line := range strings.Lines(string(out)) {
		if strings.HasPrefix(line, "func (pending) ") {
			methods = append(methods, line[len("func (pending) "):strings.Index(line, "(context")])
		}
	}
	if diff := cmp.Diff([]string{"ListC", "MakeB"}, methods); diff != "" {
		t.Errorf("stubbed methods (-want +got):\n%s", diff)
	}
	if !strings.Contains(string(out), "things.ListCRequestObject") || !strings.HasPrefix(string(out), "// Code generated by pendingapi from api/api.yaml. DO NOT EDIT.") {
		t.Errorf("the generated file does not name its contract and the api package:\n%s", out)
	}
}

// TestRunWithEveryHandler: an operation the handler type declares is left out, and when it declares them all the file
// holds the type and no method, importing nothing: it compiles until the embedding is deleted too.
func TestRunWithEveryHandler(t *testing.T) {
	dir := t.TempDir()
	write := func(name, text string) {
		t.Helper()
		if err := os.WriteFile(filepath.Join(dir, name), []byte(text), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	write("api.yaml", contract)
	write("handler.go", "package main\n\ntype api struct{}\n\nfunc (api) GetA() {}\n\nfunc (*api) MakeB() {}\n\nfunc (api) ListC() {}\n")
	if err := run(filepath.Join(dir, "api.yaml"), dir, "stubs.gen.go", "example.test/apis/things", "api", "pending"); err != nil {
		t.Fatal(err)
	}
	out, err := fs.ReadFile(os.DirFS(dir), "stubs.gen.go")
	if err != nil {
		t.Fatal(err)
	}
	want := "// Code generated by pendingapi from api/api.yaml. DO NOT EDIT.\n\npackage main\n\n" +
		"// pending answers the operations of api/api.yaml that have no handler yet.\ntype pending struct{}\n"
	if diff := cmp.Diff(want, string(out)); diff != "" {
		t.Errorf("the file of a fully handled contract (-want +got):\n%s", diff)
	}
}
